import React, { useState, useEffect } from 'react';
import API from '../api/axios';
import {
  Phone,
  MessageSquare,
  Search,
  Calendar,
  Bike,
  RefreshCw,
  Filter,
  Store,
  CreditCard
} from 'lucide-react';
import { useSocket } from '../context/SocketContext';

export default function Orders() {
  const { newOrderAlert } = useSocket();
  const [orders, setOrders] = useState([]);
  const [riders, setRiders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  const [statusFilter, setStatusFilter] = useState('all');
  const [dateFilter, setDateFilter] = useState('all');
  const [customDate, setCustomDate] = useState('');

  const fetchOrdersAndRiders = async () => {
    try {
      setLoading(true);
      const [ordRes, ridRes] = await Promise.all([
        API.get('/orders'),
        API.get('/riders')
      ]);
      setOrders(Array.isArray(ordRes.data) ? ordRes.data : []);
      setRiders(Array.isArray(ridRes.data) ? ridRes.data : []);
    } catch (err) {
      console.error('Fetch error:', err.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchOrdersAndRiders();
  }, []);

  useEffect(() => {
    if (newOrderAlert) {
      setOrders((prev) => [newOrderAlert, ...prev]);
    }
  }, [newOrderAlert]);

  const handleStatusChange = async (orderId, newStatus) => {
    const cleanId = String(orderId).replace('ORD-', '');
    try {
      await API.patch(`/orders/${cleanId}/status`, { status: newStatus });
      setOrders(orders.map((o) => (o.id === orderId ? { ...o, status: newStatus } : o)));
    } catch (err) {
      alert('Status update failed');
    }
  };

  const handleAssignRider = async (orderId, riderId) => {
    const cleanId = String(orderId).replace('ORD-', '');
    try {
      await API.patch(`/orders/${cleanId}/assign-rider`, { rider_id: riderId });
      const assignedRider = riders.find((r) => r.id === Number(riderId));
      setOrders(
        orders.map((o) =>
          o.id === orderId
            ? {
                ...o,
                rider_id: riderId,
                rider_name: assignedRider?.name,
                rider_phone: assignedRider?.phone,
                status: 'accepted'
              }
            : o
        )
      );
    } catch (err) {
      alert('Rider assignment failed');
    }
  };

  const filteredOrders = orders.filter((order) => {
    const id = String(order.id || '');
    const phone = String(order.customer_phone || '');
    const name = String(order.customer_name || '').toLowerCase();
    const query = searchQuery.toLowerCase();
    const matchesSearch = id.includes(query) || phone.includes(query) || name.includes(query);

    const currentStatus = String(order.status || 'pending').toLowerCase();
    const matchesStatus = statusFilter === 'all' || currentStatus === statusFilter.toLowerCase();

    let matchesDate = true;
    if (dateFilter !== 'all') {
      const orderDate = order.created_at ? new Date(order.created_at) : new Date();
      const now = new Date();

      if (dateFilter === 'today') {
        matchesDate = orderDate.toDateString() === now.toDateString();
      } else if (dateFilter === 'yesterday') {
        const yesterday = new Date();
        yesterday.setDate(now.getDate() - 1);
        matchesDate = orderDate.toDateString() === yesterday.toDateString();
      } else if (dateFilter === 'last7days') {
        const last7 = new Date();
        last7.setDate(now.getDate() - 7);
        matchesDate = orderDate >= last7;
      } else if (dateFilter === 'custom' && customDate) {
        const selected = new Date(customDate);
        matchesDate = orderDate.toDateString() === selected.toDateString();
      }
    }

    return matchesSearch && matchesStatus && matchesDate;
  });

  return (
    <div className="p-8 space-y-6 bg-gray-50 min-h-screen font-sans">
      <div className="flex flex-col md:flex-row justify-between md:items-center gap-4">
        <div>
          <div className="flex items-center gap-3">
            <h1 className="text-2xl font-black text-gray-900 tracking-tight">Live Orders Console</h1>
            <span className="flex items-center gap-1 text-[11px] font-bold bg-emerald-100 text-emerald-800 px-2.5 py-0.5 rounded-full">
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
              Live Sync
            </span>
          </div>
          <p className="text-sm text-gray-500">Live order management, dispatched items, and rider controls</p>
        </div>

        <div className="flex items-center gap-3">
          <div className="relative">
            <Search className="w-4 h-4 absolute left-3 top-3 text-gray-400" />
            <input
              type="text"
              placeholder="Search by ID or Phone..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9 pr-4 py-2 border border-gray-200 rounded-xl bg-white text-sm focus:outline-none focus:ring-2 focus:ring-emerald-500 w-64"
            />
          </div>
          <button
            onClick={fetchOrdersAndRiders}
            className="p-2.5 bg-white border border-gray-200 rounded-xl hover:text-emerald-600 transition-colors shadow-sm cursor-pointer"
            title="Refresh Orders"
          >
            <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin text-emerald-600' : ''}`} />
          </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-2xl border border-gray-200 shadow-sm space-y-3">
        <div className="flex items-center gap-2 overflow-x-auto pb-1 text-xs font-bold">
          <span className="text-gray-400 flex items-center gap-1 mr-1">
            <Filter className="w-3.5 h-3.5" /> Status:
          </span>
          {[
            { id: 'all', label: 'All Orders' },
            { id: 'pending', label: '⏳ Pending' },
            { id: 'confirmed', label: '✅ Confirmed' },
            { id: 'cooking', label: '🍳 Cooking' },
            { id: 'picked', label: '🛵 Picked Up' },
            { id: 'delivered', label: '🎉 Delivered' },
            { id: 'cancelled', label: '❌ Cancelled' }
          ].map((tab) => (
            <button
              key={tab.id}
              onClick={() => setStatusFilter(tab.id)}
              className={`px-3 py-1.5 rounded-xl border transition-all whitespace-nowrap cursor-pointer ${
                statusFilter === tab.id
                  ? 'bg-emerald-600 text-white border-emerald-600 shadow-sm shadow-emerald-600/20'
                  : 'bg-gray-50 text-gray-600 border-gray-200 hover:bg-gray-100'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <div className="flex flex-wrap items-center gap-2 pt-2 border-t border-gray-100 text-xs font-semibold">
          <span className="text-gray-400 flex items-center gap-1 mr-1 font-bold">
            <Calendar className="w-3.5 h-3.5" /> Date:
          </span>
          {[
            { id: 'all', label: 'All Time' },
            { id: 'today', label: 'Today' },
            { id: 'yesterday', label: 'Yesterday' },
            { id: 'last7days', label: 'Last 7 Days' },
            { id: 'custom', label: 'Custom Date' }
          ].map((df) => (
            <button
              key={df.id}
              onClick={() => setDateFilter(df.id)}
              className={`px-2.5 py-1 rounded-lg border transition-all cursor-pointer ${
                dateFilter === df.id
                  ? 'bg-slate-800 text-white border-slate-800'
                  : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
              }`}
            >
              {df.label}
            </button>
          ))}

          {dateFilter === 'custom' && (
            <input
              type="date"
              value={customDate}
              onChange={(e) => setCustomDate(e.target.value)}
              className="px-2.5 py-1 border border-emerald-500 rounded-lg text-xs bg-emerald-50/40 text-emerald-950 font-bold focus:outline-none"
            />
          )}

          <span className="ml-auto text-gray-400 text-[11px] font-bold">
            Showing: <strong className="text-gray-800">{filteredOrders.length}</strong> orders
          </span>
        </div>
      </div>

      {/* Orders List */}
      {loading ? (
        <div className="p-12 text-center text-gray-500 font-bold">Loading orders...</div>
      ) : filteredOrders.length === 0 ? (
        <div className="bg-white p-12 text-center rounded-2xl border border-gray-100 text-gray-400 font-semibold">
          No orders found matching criteria.
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
          {filteredOrders.map((order) => {
            let parsedItems = [];
            try {
              parsedItems = typeof order.items === 'string' ? JSON.parse(order.items) : (order.items || []);
            } catch { parsedItems = []; }

            return (
              <div key={order.id} className="bg-white border border-emerald-100/80 rounded-3xl p-5 shadow-sm space-y-4 hover:shadow-md transition-shadow">
                {/* Header */}
                <div className="flex justify-between items-start border-b pb-3">
                  <div>
                    <span className="px-2.5 py-1 bg-emerald-100 text-emerald-800 font-black text-xs rounded-lg inline-block mb-1">
                      {String(order.id).startsWith('ORD-') ? order.id : `ORD-${order.id}`}
                    </span>
                    <span className="text-[10px] text-gray-400 block font-medium">
                      {order.created_at ? new Date(order.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : 'Live'}
                    </span>
                  </div>

                  <div className="text-right">
                    <span className={`text-[10px] font-black px-2.5 py-1 rounded-md uppercase tracking-wider block ${
                      order.status === 'delivered'
                        ? 'bg-emerald-100 text-emerald-800'
                        : order.status === 'cancelled'
                        ? 'bg-red-100 text-red-700'
                        : 'bg-amber-100 text-amber-800'
                    }`}>
                      {order.status}
                    </span>
                    <span className="text-[9px] font-bold text-gray-400 uppercase mt-0.5 block">
                      {order.payment_method} {order.payment_status ? `(${order.payment_status})` : ''}
                    </span>
                  </div>
                </div>

                {/* Customer Details */}
                <div className="space-y-1 text-xs">
                  <h3 className="font-bold text-gray-900 text-sm">{order.customer_name}</h3>
                  <p className="text-gray-500 font-medium">{order.address || order.street_house}</p>
                  <p className="text-gray-400 text-[11px]">Area: {order.area_name || 'Selected Area'}</p>

                  <div className="flex items-center gap-2 pt-1">
                    <a
                      href={`tel:${order.customer_phone}`}
                      className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg text-xs font-bold hover:bg-emerald-100"
                    >
                      <Phone className="w-3.5 h-3.5 text-emerald-600" /> {order.customer_phone}
                    </a>
                    <a
                      href={`https://wa.me/88${order.customer_phone}`}
                      target="_blank"
                      rel="noreferrer"
                      className="flex items-center gap-1.5 px-3 py-1 bg-emerald-600 text-white rounded-lg text-xs font-bold hover:bg-emerald-700"
                    >
                      <MessageSquare className="w-3.5 h-3.5" /> WhatsApp
                    </a>
                  </div>
                </div>

                {/* ORDER ITEMS & MULTI-RESTAURANT DETAILS */}
                <div className="bg-gray-50 p-3 rounded-2xl space-y-2 border border-gray-100 text-xs">
                  <span className="text-[10px] font-black uppercase text-gray-400 block">Ordered Food Items:</span>
                  {parsedItems.length === 0 ? (
                    <p className="text-xs text-gray-500 font-bold">{order.restaurant_name || 'Restaurant Order'}</p>
                  ) : (
                    <div className="space-y-1.5 max-h-36 overflow-y-auto pr-1">
                      {parsedItems.map((it, idx) => (
                        <div key={idx} className="flex justify-between items-center text-xs">
                          <div>
                            <span className="font-bold text-gray-800">{it.qty}x {it.name}</span>
                            <span className="text-[10px] text-gray-400 block font-medium">({it.restaurant_name})</span>
                          </div>
                          <span className="font-black text-gray-900">৳{it.price * it.qty}</span>
                        </div>
                      ))}
                    </div>
                  )}

                  {order.transaction_id && (
                    <div className="pt-2 border-t border-gray-200 text-[11px] font-bold text-pink-700 flex items-center justify-between">
                      <span>TrxID:</span>
                      <span className="font-mono bg-pink-100 px-2 py-0.5 rounded">{order.transaction_id}</span>
                    </div>
                  )}
                </div>

                {/* Rider Assignment Info */}
                <div className="space-y-1 text-xs">
                  <span className="text-[10px] font-black uppercase text-gray-400 block">Assigned Rider:</span>
                  {order.rider_name ? (
                    <div className="flex items-center justify-between bg-emerald-50 p-2.5 rounded-xl border border-emerald-200">
                      <div className="flex items-center gap-2">
                        <Bike className="w-4 h-4 text-emerald-700" />
                        <div>
                          <span className="font-bold text-emerald-900 block">{order.rider_name}</span>
                          <span className="text-[10px] text-gray-500">{order.rider_phone}</span>
                        </div>
                      </div>
                      <a href={`tel:${order.rider_phone}`} className="p-1.5 bg-emerald-600 text-white rounded-lg">
                        <Phone className="w-3 h-3" />
                      </a>
                    </div>
                  ) : (
                    <select
                      onChange={(e) => handleAssignRider(order.id, e.target.value)}
                      defaultValue=""
                      className="w-full px-3 py-2 border rounded-xl bg-white text-xs font-bold text-gray-700 outline-none cursor-pointer"
                    >
                      <option value="" disabled>Assign Rider to Dispatch...</option>
                      {riders.map((r) => (
                        <option key={r.id} value={r.id}>{r.name} ({r.phone})</option>
                      ))}
                    </select>
                  )}
                </div>

                {/* Total Bill & Status Update */}
                <div className="pt-2 border-t border-gray-100 space-y-2">
                  <div className="flex justify-between items-center text-xs">
                    <span className="text-gray-400 font-bold">Delivery Fee: ৳{order.delivery_fee}</span>
                    <span className="text-base font-black text-emerald-600">Bill: ৳{order.total_amount}</span>
                  </div>

                  <div>
                    <label className="text-[10px] font-bold text-gray-400 uppercase block mb-1">Change Order Status</label>
                    <select
                      value={order.status || 'pending'}
                      onChange={(e) => handleStatusChange(order.id, e.target.value)}
                      className="w-full bg-white border border-emerald-300 text-gray-800 text-xs font-bold rounded-xl px-3 py-2 outline-none cursor-pointer focus:ring-1 focus:ring-emerald-500"
                    >
                      <option value="pending">⏳ Pending</option>
                      <option value="confirmed">✅ Confirmed</option>
                      <option value="cooking">🍳 Cooking</option>
                      <option value="picked">🛵 Picked Up / On The Way</option>
                      <option value="delivered">🎉 Delivered</option>
                      <option value="cancelled">❌ Cancelled</option>
                    </select>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
